<https://example.org/openevidence/questions/q_ankylosing_spondylitis_efficacy> a holon:ClinicalQuestionHolon ;
  holon:interior <https://example.org/openevidence/questions/q_ankylosing_spondylitis_efficacy-int> ;
  holon:boundary <https://example.org/openevidence/questions/q_ankylosing_spondylitis_efficacy-bou> ;
  holon:projection <https://example.org/openevidence/questions/q_ankylosing_spondylitis_efficacy-pro> ;
  holon:context <https://example.org/openevidence/questions/q_ankylosing_spondylitis_efficacy-con> .

<https://example.org/openevidence/drugs/adalimumab> oe:treats <https://example.org/openevidence/diseases/ankylosing_spondylitis> .

<https://example.org/openevidence/questions/q_ankylosing_spondylitis_efficacy-int> a oegen:Interior ;
  oegen:hasFact [
    a oe:Fact ;
    oe:subject <https://example.org/openevidence/drugs/adalimumab> ;
    oe:predicate oe:treats ;
    oe:object <https://example.org/openevidence/diseases/ankylosing_spondylitis> ;
    oe:confidence 0.91 ;
    oe:level "Level-1B" ;
    oe:source <https://example.org/openevidence/sources/35788492> ;
    oe:effectiveness "effective"
  ] .

<https://example.org/openevidence/questions/q_ankylosing_spondylitis_efficacy-bou> a oegen:Boundary ;
  oegen:hasFact [
    a oe:Fact ;
    oe:subject <https://example.org/openevidence/drugs/levothyroxine> ;
    oe:predicate oe:treats ;
    oe:object <https://example.org/openevidence/diseases/hypothyroidism> ;
    oe:confidence 0.26 ;
    oe:level "Level-5" ;
    oe:source <https://example.org/openevidence/sources/37738506> ;
    oe:effectiveness "inconclusive"
  ] .

<https://example.org/openevidence/questions/q_ankylosing_spondylitis_efficacy-pro> a oegen:Projection ;
  oegen:hasFact [
    a oe:Fact ;
    oe:subject <https://example.org/openevidence/drugs/methotrexate> ;
    oe:predicate oe:treats ;
    oe:object <https://example.org/openevidence/diseases/rheumatoid_arthritis> ;
    oe:confidence 0.87 ;
    oe:level "Level-1B" ;
    oe:source <https://example.org/openevidence/sources/41506743> ;
    oe:effectiveness "effective"
  ] .

<https://example.org/openevidence/questions/q_ankylosing_spondylitis_efficacy-con> a oegen:Context ;
  oegen:hasFact [
    a oe:Fact ;
    oe:subject <https://example.org/openevidence/drugs/prednisone> ;
    oe:predicate oe:treats ;
    oe:object <https://example.org/openevidence/diseases/addison_disease> ;
    oe:confidence 0.38 ;
    oe:level "Level-4" ;
    oe:source <https://example.org/openevidence/sources/36102024> ;
    oe:effectiveness "inconclusive"
  ] .
